0013: function motionDuration(level: LuxuryPreset["motionLevel"]): string {
0014:   switch (level) {
0015:     case "micro":
0016:       return "140ms";
0017:     case "standard":
0018:       return "260ms";
0019:     case "hero":
0020:       return "460ms";
0021:     case "off":
0022:     default:
0023:       return "0ms";
0024:   }
0025: }
0026: 
0027: function motionEasing(level: LuxuryPreset["motionLevel"]): string {
0028:   switch (level) {
0029:     case "hero":
0030:       return "cubic-bezier(0.22, 1, 0.36, 1)";
0031:     case "micro":
0032:       return "cubic-bezier(0.26, 0.72, 0.2, 1)";
0033:     case "off":
0034:       return "linear";
0035:     case "standard":
0036:     default:
0037:       return "cubic-bezier(0.2, 0.8, 0.2, 1)";
