0041: export function buildPresetCssVarMap(
0042:   preset: LuxuryPreset,
0043:   options?: CssVarBuildOptions
0044: ): Record<string, string> {
0045:   const safePreset = repairPreset(preset, { includeAlienTech: options?.includeAlienTech ?? false });
0046:   const style = resolveLuxuryStyle(safePreset.styleId);
0047:   const material = resolveLuxuryMaterial(safePreset.styleId, safePreset.materialId, {
0048:     includeAlienTech: options?.includeAlienTech ?? false
0049:   });
0050: 
0051:   const reducedMotion = options?.reducedMotionPreview ?? false;
0052:   const motionState = reducedMotion || safePreset.motionLevel === "off" ? "off" : "on";
0053:   const motionMs = reducedMotion ? "0ms" : motionDuration(safePreset.motionLevel);
0054:   const motionEase = reducedMotion ? "linear" : motionEasing(safePreset.motionLevel);
0055: 
0056:   return {
0057:     ...style.baseCssVars,
0058:     ...material.cssVars,
0059:     "--luxury-style-id": safePreset.styleId,
0060:     "--luxury-surface-id": safePreset.surfaceId,
0061:     "--luxury-material-id": safePreset.materialId,
0062:     "--luxury-perf-profile": safePreset.perfProfile,
0063:     "--luxury-motion-level": safePreset.motionLevel,
0064:     "--luxury-motion-state": motionState,
0065:     "--luxury-motion-duration": motionMs,
0066:     "--luxury-motion-easing": motionEase,
0067:     "--luxury-blur-px": `${safePreset.knobs.blurStrengthPx.toFixed(2)}px`,
0068:     "--luxury-grain-opacity": safePreset.knobs.grainOpacity.toFixed(3),
0069:     "--luxury-grid-opacity": safePreset.knobs.gridOpacity.toFixed(3),
0070:     "--luxury-specular-opacity": safePreset.knobs.specularIntensity.toFixed(3)
0071:   };
0072: }
