0074: export function cssVarMapToText(map: Readonly<Record<string, string>>): string {
0075:   const lines = Object.entries(map)
0076:     .sort((left, right) => left[0].localeCompare(right[0]))
0077:     .map(([key, value]) => `  ${key}: ${value};`);
0078: 
0079:   return `:root {\n${lines.join("\n")}\n}`;
0080: }
