0087:   if (typeof window === "undefined") {
0088:     return false;
0089:   }
0090: 
0091:   const blob = new Blob([content], { type: "application/json;charset=utf-8" });
0092:   const url = URL.createObjectURL(blob);
0093:   const anchor = document.createElement("a");
0094:   anchor.href = url;
0095:   anchor.download = filename;
0096:   anchor.rel = "noopener";
0097:   anchor.style.display = "none";
0098:   document.body.appendChild(anchor);
0099:   anchor.click();
0100:   document.body.removeChild(anchor);
0101:   URL.revokeObjectURL(url);
0102:   return true;
0103: }
