0043: function isRecord(value: unknown): value is Record<string, unknown> {
0044:   return typeof value === "object" && value !== null && !Array.isArray(value);
0045: }
0046: 
0047: function asString(value: unknown): string | null {
0048:   return typeof value === "string" ? value : null;
0049: }
0050: 
0051: function asNumber(value: unknown): number | null {
0052:   if (typeof value === "number" && Number.isFinite(value)) {
0053:     return value;
0054:   }
0055:   return null;
0056: }
0057: 
0058: function asStringArray(value: unknown): string[] | null {
0059:   if (!Array.isArray(value)) {
0060:     return null;
0061:   }
0062: 
0063:   const output: string[] = [];
0064:   for (const entry of value) {
0065:     if (typeof entry !== "string") {
0066:       return null;
0067:     }
0068:     output.push(entry);
0069:   }
0070:   return output;
0071: }
